import { db, requireCron, response, runEnd, runStart, SITE, publishFromCandidate } from "../_shared/greener.ts";
function centralStart() { const parts = new Intl.DateTimeFormat("en-US", { timeZone: "America/Chicago", year: "numeric", month: "2-digit", day: "2-digit", timeZoneName: "longOffset" }).formatToParts(new Date()); const get = (type: string) => parts.find((part) => part.type === type)?.value ?? ""; const offset = get("timeZoneName").replace("GMT", "") || "-06:00"; return new Date(`${get("year")}-${get("month")}-${get("day")}T00:00:00${offset}`); }
Deno.serve(async (req) => { const denied = requireCron(req); if (denied) return denied; const id = await runStart("greener-daily-story-watchdog"); try { const { count, error } = await db.from("site_news").select("id", { count: "exact", head: true }).eq("site", SITE).eq("status", "published").gte("published_at", centralStart().toISOString()).in("story_type", ["daily", "breaking"]); if (error) throw error; if ((count ?? 0) > 0) { await runEnd(id, "success", { skipped: 1 }, undefined, { intervention: false }); return response({ intervention: false }); } const r = await publishFromCandidate("greener-daily-story-watchdog"); await runEnd(id, r.published ? "success" : "failed", { created: r.published ? 1 : 0 }, r.published ? undefined : r.reason, { intervention: true }); return response({ intervention: true, ...r }); } catch (e) { await runEnd(id, "failed", {}, e); return response({ error: "watchdog failed" }, 500); } });

